function subCountRec(i, j, txt, pat)
{
    // If the pattern is empty, there is exactly one way to
    // match it (by choosing nothing)
    if (j === 0)
        return 1;

    // If txt is empty but pat is not, it's impossible to
    // form the subsequence
    if (i === 0)
        return 0;

