        if (pat.charAt(i - 1) != txt.charAt(j - 1)) {
            memo[i][j] = countSubsequences(i, j - 1, pat,
                                           txt, memo);
        }
        else {

            // Both characters match
            memo[i][j] = countSubsequences(i, j - 1, pat,
                                           txt, memo)
                         + countSubsequences(
                             i - 1, j - 1, pat, txt, memo);
